function mulberry(a) { return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
export let R = Math.random;
export function setRng(f) { R = f; }
const pick = (a) => a[Math.floor(R() * a.length)];
const chance = (p) => R() < p;
const int = (a, b) => a + Math.floor(R() * (b - a + 1));
const pickN = (a, n) => { const c = a.slice(), out = []; while (out.length < n && c.length) out.push(c.splice(Math.floor(R() * c.length), 1)[0]); return out; };
const wpick = (items) => { const t = items.reduce((s, i) => s + i[1], 0); let x = R() * t; for (const i of items) { x -= i[1]; if (x <= 0) return i[0]; } return items[0][0]; };
const G = (s, f) => String(s).replace(/\{([^|}]*)\|([^}]*)\}/g, (_, m, w) => (f ? w : m));
const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);
const low = (s) => (s ? s.charAt(0).toLowerCase() + s.slice(1) : s);
const plural = (n, a, b, c) => { const t = Math.abs(n) % 100, u = t % 10; return t > 10 && t < 20 ? c : u === 1 ? a : u >= 2 && u <= 4 ? b : c; };
const years = (n) => `${n} ${plural(n, 'год', 'года', 'лет')}`;
const esc = (s) => String(s).replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const hash = (n, k) => { let x = (n ^ Math.imul(k + 1, 0x9E3779B1)) | 0; x = Math.imul(x ^ (x >>> 16), 0x85EBCA6B); x = Math.imul(x ^ (x >>> 13), 0xC2B2AE35); return ((x ^ (x >>> 16)) >>> 0) / 4294967296; };
const hpick = (c, k, arr) => arr[Math.floor(hash(c.seed, k) * arr.length)];
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

